// Clean and validate the request. Nothing downstream trusts the browser.
const b = $input.first().json.body ?? $input.first().json;
const CHANNELS = ['email', 'chat', 'web_form', 'social'];
const TIERS = ['free', 'standard', 'premium', 'unknown'];
const str = (v) => (typeof v === 'string' ? v : '');

// Stop the customer text from closing our <ticket> wrapper early.
const text = str(b.text).replace(/<\/?ticket>/gi, '').trim();

// Optional "email me the result" address. Same shape check as the page,
// plus a length cap and no whitespace (blocks header-injection tricks).
const rawEmail = str(b.notifyEmail).trim().toLowerCase();
const emailOk = rawEmail.length > 0 && rawEmail.length <= 254 && /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(rawEmail);

return [{
  json: {
    valid: b.action === 'classify_ticket' && text.length >= 20 && text.length <= 3000,
    channel: CHANNELS.includes(b.channel) ? b.channel : 'email',
    customerTier: TIERS.includes(b.customerTier) ? b.customerTier : 'unknown',
    subject: str(b.subject).replace(/<\/?ticket>/gi, '').trim().slice(0, 150),
    text,
    notifyEmail: emailOk ? rawEmail : null, // a bad address is ignored, the ticket is still classified
    turnstileToken: str(b.turnstileToken),
  },
}];

// Playground rate limit, kept in this workflow's own static data.
// Only persists on ACTIVE (production) runs, not manual test runs.
// To share the Testarosa chat budget instead, replace this node with the
// check_rate_limit call using a separate key like 'playground-support'.
const item = $('Clean input').first().json;
const sd = $getWorkflowStaticData('global');
const now = Date.now();
const HOUR = 3600 * 1000;
const DAY = 24 * HOUR;

const MAX_REQUESTS_PER_HOUR = 30;          // whole demo, all visitors
const MAX_EMAILS_PER_ADDRESS_PER_DAY = 3;  // one inbox
const MAX_EMAILS_PER_DAY = 40;             // whole demo

sd.hits = (sd.hits || []).filter((t) => now - t < HOUR);
sd.mailAll = (sd.mailAll || []).filter((t) => now - t < DAY);
sd.mailBy = sd.mailBy || {};
for (const k of Object.keys(sd.mailBy)) {
  sd.mailBy[k] = sd.mailBy[k].filter((t) => now - t < DAY);
  if (sd.mailBy[k].length === 0) delete sd.mailBy[k];
}

let allowed = true;
let notifyEmail = item.notifyEmail;

if (sd.hits.length >= MAX_REQUESTS_PER_HOUR) {
  allowed = false;
} else {
  sd.hits.push(now);
  if (notifyEmail) {
    const mine = sd.mailBy[notifyEmail] || [];
    if (mine.length >= MAX_EMAILS_PER_ADDRESS_PER_DAY || sd.mailAll.length >= MAX_EMAILS_PER_DAY) {
      notifyEmail = null; // still classify, just skip the email
    } else {
      mine.push(now);
      sd.mailBy[notifyEmail] = mine;
      sd.mailAll.push(now);
    }
  }
}

return [{ json: { ...item, notifyEmail, allowed } }];

// Server-side check so garbage never leaves n8n. The page checks again.
const r = $input.first().json.output ?? $input.first().json;
const ctx = $('Rate limit').first().json;
const CAT = ['billing','account_access','technical_issue','bug_report','feature_request','refund_cancellation','shipping_delivery','general_question','spam_abuse'];
const PRI = ['urgent','high','normal','low'];
const SEN = ['angry','frustrated','neutral','positive'];
const LVL = ['high','medium','low'];
const s = (v) => (typeof v === 'string' ? v.trim() : '');
const list = (v) => (Array.isArray(v) ? v.map(s).filter(Boolean) : []);

if (!r || !CAT.includes(r.category) || !PRI.includes(r.priority)) {
  return [{ json: { ok: false } }];
}

const result = {
  category: r.category,
  priority: r.priority,
  sentiment: SEN.includes(r.sentiment) ? r.sentiment : 'neutral',
  confidence: LVL.includes(r.confidence) ? r.confidence : 'low',
  language: s(r.language),
  summary: s(r.summary),
  suggestedTeam: s(r.suggestedTeam),
  routingReason: s(r.routingReason),
  keyPoints: list(r.keyPoints).slice(0, 5),
  tags: list(r.tags).slice(0, 6),
  humanReview: { required: r.humanReview?.required === true, reason: s(r.humanReview?.reason) },
  suggestedReply: s(r.suggestedReply),
  missingInfo: list(r.missingInfo).slice(0, 5),
};

// Fixed rules beat the model: sensitive tickets always get a person.
if (result.category === 'refund_cancellation' || result.sentiment === 'angry') {
  result.humanReview.required = true;
  if (!result.humanReview.reason) result.humanReview.reason = 'Sensitive ticket. A person should review it before any reply.';
}

return [{ json: { ok: true, result, notifyEmail: ctx.notifyEmail || null } }];

// Builds the result email (same look as the Incident Analyzer one).
// Everything that came from the customer or the model is HTML-escaped.
const d = $input.first().json;
const r = d.result;
const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const CATEGORY = {
  billing: 'Billing & payments', account_access: 'Account access', technical_issue: 'Technical issue',
  bug_report: 'Bug report', feature_request: 'Feature request', refund_cancellation: 'Refund / cancellation',
  shipping_delivery: 'Shipping & delivery', general_question: 'General question', spam_abuse: 'Spam / abuse',
};
const PRIORITY = { urgent: 'URGENT', high: 'HIGH', normal: 'NORMAL', low: 'LOW' };
const cat = CATEGORY[r.category] || r.category;
const pri = PRIORITY[r.priority] || r.priority.toUpperCase();

const h3 = (t) => `<h3 style="font-size:16px;margin:24px 0 4px 0;color:#202124;">${t}</h3>`;
const ul = (items) => items.length
  ? `<ul style="margin:6px 0 0 0;padding-left:22px;">${items.map((i) => `<li style="margin:4px 0;">${esc(i)}</li>`).join('')}</ul>`
  : '';
const pill = (t) => `<span style="display:inline-block;margin:2px 4px 2px 0;padding:2px 10px;border:1px solid #dadce0;border-radius:999px;font-size:12px;color:#5f6368;">${esc(t)}</span>`;

const review = r.humanReview.required
  ? `<div style="margin:6px 0 0 0;padding:10px 14px;background:#fef7e0;border-left:4px solid #f9ab00;"><strong>Human review needed.</strong> ${esc(r.humanReview.reason)}</div>`
  : `<p style="margin:6px 0 0 0;color:#5f6368;">No mandatory human review. ${esc(r.humanReview.reason)}</p>`;

const html = `
<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;color:#202124;max-width:640px;">
  <h2 style="font-size:22px;margin:0 0 4px 0;">${esc(pri)} &middot; ${esc(cat)}</h2>
  <p style="margin:0 0 14px 0;color:#5f6368;font-size:13px;">Confidence: ${esc(r.confidence)} &nbsp;|&nbsp; Sentiment: ${esc(r.sentiment)}${r.language ? ' &nbsp;|&nbsp; Language: ' + esc(r.language) : ''}</p>
  <p style="margin:0;">${esc(r.summary)}</p>

  ${h3('Routing')}
  <p style="margin:6px 0 0 0;"><strong>${esc(r.suggestedTeam)}</strong><br><span style="color:#5f6368;">${esc(r.routingReason)}</span></p>

  ${r.keyPoints.length ? h3('Key points') + ul(r.keyPoints) : ''}
  ${r.tags.length ? h3('Tags') + '<div style="margin-top:6px;">' + r.tags.map(pill).join('') + '</div>' : ''}

  ${h3('Human review')}
  ${review}

  ${h3('Suggested reply (draft only, not sent to anyone)')}
  <div style="margin:6px 0 0 0;padding:12px 16px;background:#f6f6f6;border-left:4px solid #dadce0;white-space:pre-wrap;">${esc(r.suggestedReply)}</div>

  ${r.missingInfo.length ? h3('Still unknown: ask the customer') + ul(r.missingInfo) : ''}

  <hr style="border:none;border-top:1px solid #bdc1c6;margin:28px 0 12px 0;">
  <p style="font-size:12px;color:#80868b;margin:0;">Sent from the Testarosa Playground demo. This is an AI triage suggestion, not a decision. Verify before acting.</p>
</div>`;

return [{ json: { to: d.notifyEmail, subject: `[${pri}] Ticket triage: ${cat}`, html } }];
